import CryptoKit
import Foundation

/// Wire primitives shared with the server (app/services/evidence/crypto.rb).
/// desktop/PROTOCOL.md is the specification; Tests/…/test-vectors.json is
/// generated by the Ruby side and checked here. Only CryptoKit primitives are
/// used: SHA-256 and ChaCha20-Poly1305.
public enum EvidenceProtocol {
    public static let zeroHash = String(repeating: "0", count: 64)
    static let chainDomain = Data("hkt-chain-v1\n".utf8)
    static let timelapseDomain = Data("hkt-timelapse-v1\n".utf8)
    static let commitDomain = Data("hkt-beacon-secret-v1\n".utf8)
    public static let frameAAD = Data("hkt-frame-v1".utf8)

    public static func sha256(_ data: Data) -> Data { Data(SHA256.hash(data: data)) }
    public static func sha256Hex(_ data: Data) -> String { sha256(data).hex }

    /// hash = H(domain || prev || beacon_value || H(payload))
    public static func chainHash(prev: String, beaconValue: String, payload: Data) -> String {
        var input = chainDomain
        input.append(Data(hex: prev))
        input.append(Data(hex: beaconValue))
        input.append(sha256(payload))
        return sha256Hex(input)
    }

    public static func beaconCommitment(secret: String) -> String {
        var input = commitDomain
        input.append(Data(hex: secret))
        return sha256Hex(input)
    }

    /// The second of this minute when the timelapse frame is due. Only the
    /// server's beacon decides it, so the client cannot pick when it is watched.
    public static func timelapseSecond(beaconValue: String, deviceUID: String) -> Int {
        var input = timelapseDomain
        input.append(Data(hex: beaconValue))
        input.append(Data(deviceUID.utf8))
        return Int(sha256(input)[0]) % 60
    }

    public static func merkleLeaf(salt: String, path: String, content: Data) -> String {
        var input = Data([0])
        input.append(Data(hex: salt))
        input.append(Data(path.utf8))
        input.append(0)
        input.append(sha256(content))
        return sha256Hex(input)
    }

    public static func merkleLeaf(salt: String, path: String, contentHash: Data) -> String {
        var input = Data([0])
        input.append(Data(hex: salt))
        input.append(Data(path.utf8))
        input.append(0)
        input.append(contentHash)
        return sha256Hex(input)
    }

    public static func merkleRoot(_ leaves: [String]) -> String {
        guard !leaves.isEmpty else { return zeroHash }
        var level = leaves.map { Data(hex: $0) }
        while level.count > 1 {
            var next: [Data] = []
            var index = 0
            while index < level.count {
                if index + 1 < level.count {
                    var input = Data([1])
                    input.append(level[index])
                    input.append(level[index + 1])
                    next.append(sha256(input))
                } else {
                    next.append(level[index])
                }
                index += 2
            }
            level = next
        }
        return level[0].hex
    }

    /// nonce(12) || ciphertext || tag(16), the same layout the server opens.
    public static func seal(_ plaintext: Data, key: SymmetricKey) throws -> Data {
        try ChaChaPoly.seal(plaintext, using: key, authenticating: frameAAD).combined
    }

    public static func open(_ blob: Data, key: SymmetricKey) throws -> Data {
        try ChaChaPoly.open(ChaChaPoly.SealedBox(combined: blob), using: key, authenticating: frameAAD)
    }

    /// PKCE (RFC 7636, S256).
    public static func pkcePair() -> (verifier: String, challenge: String) {
        var bytes = [UInt8](repeating: 0, count: 48)
        _ = SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes)
        let verifier = Data(bytes).base64URL
        return (verifier, sha256(Data(verifier.utf8)).base64URL)
    }
}

public extension Data {
    init(hex: String) {
        var data = Data(capacity: hex.count / 2)
        var index = hex.startIndex
        while index < hex.endIndex, let next = hex.index(index, offsetBy: 2, limitedBy: hex.endIndex) {
            if let byte = UInt8(hex[index ..< next], radix: 16) { data.append(byte) }
            index = next
        }
        self = data
    }

    var hex: String { map { String(format: "%02x", $0) }.joined() }

    var base64URL: String {
        base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
    }

    static func random(_ count: Int) -> Data {
        var bytes = [UInt8](repeating: 0, count: count)
        _ = SecRandomCopyBytes(kSecRandomDefault, count, &bytes)
        return Data(bytes)
    }
}
